function ProductCard({ p, addToCart }) {
  return (
    <div style={{
      border: "1px solid #ccc",
      padding: 10,
      width: 220,
      margin: 10
    }}>
      <img src={p.image} width="100%" />

      <h4>{p.name}</h4>

      <p style={{ color: "red" }}>
        {p.price.toLocaleString()} VND
      </p>

      <button onClick={() => addToCart(p)}>
        🛒 Thêm vào giỏ
      </button>
    </div>
  );
}

export default ProductCard;s
